    if bin_residual == bin_capacity {
        score += mean_residual * 1.5;
        score += (open_bins_count as f64) * 0.5;
    } else {
        // 2. Best-Fit logic: reward bins that leave very little space (low post_residual).
        // 3. Lookahead logic: if the next item fits perfectly into the remaining space, 
        // heavily reward this bin to create a "perfect pair".
        if next_item_size > 0 && next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            if gap == 0 {
                score -= 50.0; // Perfect match reward
            } else {
                score -= (40.0 / (gap as f64 + 1.0)); // Proximity reward
            }
        }

        // 4. Penalty for "fragmentation": if the post_residual is small but > 0, 
        // it creates a "dead zone" that cannot fit most items (items are >= 10).
        if post_residual > 0 && post_residual < 10 {
            score += 30.0;
        }

        // 5. If this is the last fitting bin, prioritize it to avoid opening a new bin 
        // unnecessarily (unless the fit is truly awful).
        if fitting_bins_count == 1 {
            score -= 10.0;
        }
    }

    // 6. Dynamic Scaling: As we approach the end of the stream, prioritize 
    // filling existing bins more aggressively to consolidate.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Strategy: Minimize post_residual (Best Fit), but penalize "fragmentation" 
    // where post_residual is too small to fit common items, and leverage 
    // lookahead to reserve space for the next item.

    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Fragmentation Penalty: If post_residual is between 1 and 9, it's likely "dead space"
    // because the minimum item size is 10. We heavily penalize this.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead Synergy: If the next item fits into the current post_residual,
    // prioritize this bin to reduce the number of bins used long-term.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0 * (1.0 - progress);
    }

    // 3. Global Density Balancing: If we have many open bins, penalize opening a new one.
    // If bin_residual == bin_capacity, we are evaluating a NEW bin.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
