            score += 40.0 + (open_bins_count as f64 * 2.0);
        }
    } else {
        // 4. Tightness Reward: Favor bins that are already closer to being full 
        // to consolidate usage.
        score -= (bin_capacity - bin_residual) as f64 * 0.1;
    }

    // 5. Last Chance Heuristic: If this is the only bin that can fit the item,
    // lower the score to ensure we don't unnecessarily open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

