pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize creating tiny gaps that are unlikely to be filled later (1..10 is "dead space").
    // We use a non-linear penalty that scales with progress: as we near the end of the stream,
    // small residuals become increasingly expensive.
    let dead_space_penalty = if post > 0.0 && post < 15.0 {
        (15.0 - post).powf(1.5) * (1.0 + progress * 2.0)
    } else {
        0.0
    };

    // Reward placing items in bins that bring the bin closer to the global mean residual,
    // effectively balancing load across bins.
    let balance_reward = (post - mean_residual).abs() * 0.5;

    // Lookahead logic: If the next item is large (e.g., > 50), we penalize leaving a 
    // post_residual that is too small to accommodate it.
    let lookahead_penalty = if next_item_size > 0 && post < next_item_size as f64 {
        (next_item_size as f64 - post) * 1.2
    } else {
        0.0
    };

    // Base score is the post_residual itself (Best Fit strategy).
    // We modify it with our non-linear coupling terms.
    let mut score = post + dead_space_penalty + balance_reward + lookahead_penalty;

    // Special handling for the "New Bin" candidate (bin_residual == bin_capacity).
    // We make opening a new bin expensive early on, but cheaper as the stream progresses
    // if the current fitting options are poor (high post_residual).
    if bin_residual == bin_capacity {
        score = 80.0 + (progress * 20.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
