        if post_residual < next_item_size {
            score += 75.0; // Heavy penalty for blocking the next item
        } else {
            // Reward residuals that fit the next item plus a small buffer, 
            // minimizing the "stranded" space.
            let slack = post_residual - next_item_size;
            if slack < 10 {
                score -= 25.0; 
            }
        }
    }

    // 3. Global Bin Utilization: 
    // Normalize new bin cost against the open bin density.
    if bin_residual == bin_capacity {
        // Only open a new bin if the average residual of current bins is high (indicating poor fit)
        // or if we have very few bins open (keep footprint small).
        let new_bin_base_cost = 55.0;
        score += new_bin_base_cost - (mean_residual * 0.8) + (open_bins_count as f64 * 0.2);
    } else {
        // Prioritize bins that are already tight (Best Fit)
        score += (bin_capacity - bin_residual) as f64 * 0.1;
    }

    // 4. End-of-Stream Compaction:
    // As we approach the end of the stream, prioritize completing existing bins
    // to avoid leaving half-empty bins at the very end.
    let progress = step_index as f64 / total_items as f64;
    score -= (progress * 15.0) * (1.0 - (post_residual as f64 / bin_capacity as f64));

    // 5. Critical Constraint:
    // If only one bin can fit the item, it must be the top priority.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items as f64;

