    let mut score = post_residual as f64;

    // 1. Adaptive Dead-Zone Mitigation:
    // Avoid creating narrow slices that cannot fit typical items (1-15).
    if post_residual > 0 && post_residual < 16 {
        score += 35.0 - (progress * 10.0);
    }

    // 2. New Bin Thresholding:
    // Scale the cost of opening a new bin based on the scarcity of current options.
    if is_new_bin {
        // As mean_residual decreases, existing bins are tighter; increase cost to open new ones.
        // If fitting_bins_count is low, we are forced to open new bins; reduce penalty.
        let urgency = if fitting_bins_count == 0 { -20.0 } else { 0.0 };
        score += 48.0 - (mean_residual * 0.4) + urgency;
    } else {
        // 3. Strategic Lookahead:
        // Penalize blocking the next item, but reward residuals that are "optimal" for it.
        if next_item_size > 0 {
            if post_residual < next_item_size {
                score += 45.0; // Penalty for stranding the next item
            } else {
                // Reward residuals that are close to next_item_size (tight fit for upcoming)
                let gap = (post_residual - next_item_size) as f64;
                score += gap * 0.2;
            }
        }

        // 4. Fitting Pressure:
        // If this is the only bin that fits the current item, prioritize it strongly.
        if fitting_bins_count == 1 {
            score -= 120.0;
        }
    }

    // 5. Harmonic Versatility:
    // Encourage residuals that are multiples of 25 (common capacity factors).
    score += (post_residual % 25) as f64 * 0.5;

    // 6. Global Balancing:
    // Prevent extreme variance in bin utilization.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.05;

    // 7. Temporal Aggression:
    // As stream progresses, prioritize tightest fits to close out bins.
    score -= progress * 15.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
