    }

    // 4. Fitting constraints: Aggressively favor the last available bin to prevent new bin creation.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // 5. New bin threshold: Adaptive cost.
    // As we reach the end of the stream, the cost to open a new bin decreases to allow 
    // for final clean-up, but increases if we are early to force tight packing.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items as f64;
        let base_new_bin_cost = 65.0 - (mean_residual * 0.8);
        score += base_new_bin_cost * (1.0 - (progress * 0.3));
    }

    // 6. Density Pressure: Penalize bins that have a high residual relative to the mean.
    // This forces the algorithm to focus on filling the emptiest bins first.
    if bin_residual > (mean_residual as u32) {
        score += (bin_residual - mean_residual as u32) as f64 * 0.2;
    }

    // 7. Global progression: Minor bias towards finishing earlier bins.
    score -= (step_index as f64 / total_items as f64) * 12.0;

    score
