    // 4. Tightness Constraint:
    // If we have many bins open, prioritize filling the tightest fit to encourage bin exhaustion.
    if fitting_bins_count > 0 {
        let tightness = (item_size as f64 / bin_capacity as f64);
        score -= (tightness * 20.0);
