    let progress = step_index as f64 / total_items as f64;
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // 1. Dynamic Dead Zone: Tightened penalty based on residual potential
    if post_residual > 0 && post_residual < 45 {
        score += 135.0 + (45.0 - post_residual as f64) * 10.5;
    }

    // 2. Harmonic Residual Smoothing: Favor residuals that align with common item distributions
    score += (post_residual % 13) as f64 * 1.5;

    // 3. Lookahead Optimization: Enhanced fit-bonus for immediate future items
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let fit_bonus = 110.0 + (next_item_size as f64 * 1.3);
            score -= if post_residual == next_item_size { fit_bonus * 5.0 } else { fit_bonus * 2.5 };
        } else if post_residual > 0 {
            score += 135.0 * (1.0 - (post_residual as f64 / next_item_size as f64));
        }
    }

    // 4. Fitting Scarcity: Exponentially punish opening new bins when capacity is available
    if fitting_bins_count > 0 && fitting_bins_count <= 20 {
        score -= (21.0 - fitting_bins_count as f64).powf(2.9) * 58.0;
    }

    // 5. New Bin Adaptive Cost: Increased cost for new bins, scaling with progress
    if is_new_bin {
        let avg_fill = (bin_capacity as f64 - mean_residual) / bin_capacity as f64;
        score += 185.0 - (avg_fill * 125.0) + (progress * 280.0);
        if mean_residual < 27.0 { score += 70.0; }
        if item_size < 42 { score += 110.0; }
    } else {
        score -= progress * 145.0;
    }

    // 6. Fill Density Bias: Quadratic reward for high-utilization
    if fill_ratio > 0.40 {
        score -= 150.0 * (fill_ratio.powi(2));
    }

    // 7. Variance Damping: Penalize bins that deviate from the global mean residual
    let dev = (post_residual as f64 - mean_residual).abs();
    if dev > 3.5 {
        score += dev * 5.5;
    }

    // 8. Global Coupling: Penalize open bin count to force consolidation
    if open_bins_count > 2 && progress < 0.99 {
        score += (open_bins_count as f64 * 7.0) * (1.0 + progress);
    }

    // 9. Residual Tail-End Check: Hard penalty for microscopic gaps
    if post_residual > 0 && post_residual < 16 {
        score += 110.0;
    }

    // 10. Density-Residual Interaction: If bin is nearly full, prioritize perfect fits
    if fill_ratio > 0.88 && post_residual < 22 {
        score -= 105.0;
    }

    // 11. Anti-fragmentation: Specifically target mid-to-large items
    if item_size > 30 && item_size < 85 && post_residual > 0 && post_residual < 35 {
        score -= 75.0 * (1.0 - (post_residual as f64 / 35.0));
    }

    // 12. Strategic New Bin Avoidance: Bonus for fitting large items in existing bins
    if item_size > 50 && !is_new_bin {
        score -= 90.0;
    }

    // 13. Late-stage compaction correction
    if progress > 0.80 && !is_new_bin {
        score -= (post_residual as f64) * 0.8;
    }

    score
}

