    let progress = step_index as f64 / total_items as f64;
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // 1. Refined Dead Zone: Heavily penalize mid-range residuals that hinder future large items
    if post_residual > 0 && post_residual < 52 {
        score += 135.0 + (52.0 - post_residual as f64) * 10.2;
    }

    // 2. Harmonic Residual Smoothing: Favor residuals that align with common item distributions
    score += (post_residual % 11) as f64 * 1.8;

    // 3. Lookahead Optimization: Tighten fit-bonus for next_item_size
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let fit_bonus = 105.0 + (next_item_size as f64 * 1.25);
            score -= if post_residual == next_item_size { fit_bonus * 5.8 } else { fit_bonus * 2.4 };
        } else if post_residual > 0 {
            score += 140.0 * (1.0 - (post_residual as f64 / next_item_size as f64));
        }
    }

    // 4. Fitting Scarcity: Exponentially punish opening new bins when capacity is available
    if fitting_bins_count > 0 && fitting_bins_count <= 22 {
        score -= (23.0 - fitting_bins_count as f64).powf(2.9) * 65.0;
    }

    // 5. New Bin Adaptive Cost: Dynamic thresholding based on mean_residual state
    if is_new_bin {
        let avg_fill = (bin_capacity as f64 - mean_residual) / bin_capacity as f64;
        score += 210.0 - (avg_fill * 140.0) + (progress * 310.0);
        if mean_residual < 32.0 { score += 75.0; }
        if item_size < 45 { score += 110.0; }
    } else {
        score -= progress * 155.0;
    }

    // 6. Fill Density Bias: Cubic weight for high-utilization bins
    if fill_ratio > 0.55 {
        score -= 160.0 * (fill_ratio.powi(3));
    }

    // 7. Variance Damping: Aggressive penalty for exceeding mean residual
    let dev = (post_residual as f64 - mean_residual).abs();
    if dev > 6.0 {
        score += dev * 5.8;
    }

    // 8. Global Consolidation: Penalize open bin count more strictly as stream progresses
    if open_bins_count > 1 {
        score += (open_bins_count as f64 * 7.2) * (1.0 + (progress * 0.5));
    }

    // 9. Residual Tail-End Check: Hard penalty for microscopic gaps
    if post_residual > 0 && post_residual < 16 {
        score += 125.0;
    }

    // 10. Density-Residual Interaction: Perfect fit priority
    if fill_ratio > 0.94 && post_residual < 12 {
        score -= 110.0;
    }

    // 11. Anti-fragmentation: Mid-to-large item focus
    if item_size > 35 && item_size < 85 && post_residual > 0 && post_residual < 35 {
        score -= 75.0 * (1.0 - (post_residual as f64 / 35.0));
    }

    // 12. Large Item Strategic Placement
    if item_size > 60 && !is_new_bin {
        score -= 95.0;
    }

    // 13. Late-stage compaction correction
    if progress > 0.85 && !is_new_bin {
        score -= (post_residual as f64) * 0.8;
    }

    score
}

