    // Harmonic-inspired logic: Reward filling bins to specific capacity tiers
    // Favor residuals that align with common item sizes (e.g., multiples of 20)
    let modulo_penalty = (post_residual % 20) as f64;
    score += modulo_penalty * 0.5;

    // Lookahead logic: If the next item fits into the current post_residual, prioritize this bin
    if next_item_size > 0 && next_item_size <= post_residual {
