    // Encourage density: penalize bins that are sparsely used
    let utilization = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= utilization * 10.0;

    // Adjust based on remaining stream progression
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        // Toward the end, be more aggressive about closing bins
        score -= (1.0 - utilization) * 20.0;
    }

    score
}

