    let progress = step_index as f64 / total_items as f64;
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // 1. Refined Dead Zone: Penalize residuals that create unusable space, specifically targeting 15-45 range
    if post_residual > 0 && post_residual < 46 {
        score += 135.0 + (46.0 - post_residual as f64) * 10.5;
    }

    // 2. Harmonic Residual Smoothing: Reduced alignment bias for more flexibility
    score += (post_residual % 11) as f64 * 1.2;

    // 3. Lookahead Optimization: Aggressive fit-bonus for next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let fit_bonus = 105.0 + (next_item_size as f64 * 1.25);
            score -= if post_residual == next_item_size { fit_bonus * 4.8 } else { fit_bonus * 2.4 };
        } else if post_residual > 0 {
            score += 125.0 * (1.0 - (post_residual as f64 / next_item_size as f64));
        }
    }

    // 4. Fitting Scarcity: Punish opening new bins when capacity is available; shifted for better density
    if fitting_bins_count > 0 && fitting_bins_count <= 20 {
        score -= (21.0 - fitting_bins_count as f64).powf(2.9) * 58.0;
    }

    // 5. New Bin Adaptive Cost: Dynamic penalty based on global packing state
    if is_new_bin {
        let avg_fill = (bin_capacity as f64 - mean_residual) / bin_capacity as f64;
        score += 190.0 - (avg_fill * 125.0) + (progress * 290.0);
        if mean_residual < 27.0 { score += 65.0; }
        if item_size < 42 { score += 105.0; }
    } else {
        score -= progress * 150.0;
    }

    // 6. Fill Density Bias: Quadratic reward for high-utilization
    if fill_ratio > 0.40 {
        score -= 150.0 * (fill_ratio.powi(2));
    }

    // 7. Variance Damping: Penalize bins that deviate from the global mean residual
    let dev = (post_residual as f64 - mean_residual).abs();
    if dev > 4.5 {
        score += dev * 4.8;
    }

    // 8. Global Coupling: Force consolidation with tighter constraints
    if open_bins_count > 2 && progress < 0.98 {
        score += (open_bins_count as f64 * 7.5) * (1.0 + progress);
    }

    // 9. Residual Tail-End Check: Hard penalty for microscopic gaps (sub-16)
    if post_residual > 0 && post_residual < 16 {
        score += 110.0;
    }

    // 10. Density-Residual Interaction: If bin is nearly full, prioritize perfect fits
    if fill_ratio > 0.88 && post_residual < 20 {
        score -= 100.0;
    }

    // 11. Anti-fragmentation: Specifically target mid-range waste
    if item_size > 35 && item_size < 85 && post_residual > 0 && post_residual < 35 {
        score -= 70.0 * (1.0 - (post_residual as f64 / 35.0));
    }

    // 12. Strategic New Bin Avoidance: Bonus for fitting large items in existing bins
    if item_size > 50 && !is_new_bin {
        score -= 85.0;
    }

    // 13. Late-stage compaction correction: Boosted impact
    if progress > 0.85 && !is_new_bin {
        score -= (post_residual as f64) * 0.75;
    }

    score
}

