    let progress = step_index as f64 / total_items as f64;
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // 1. Adaptive Dead Zone: Shifted threshold to 52 for tighter residual control
    if post_residual > 0 && post_residual < 52 {
        score += 145.0 + (52.0 - post_residual as f64) * 11.2;
    }

    // 2. Harmonic Residual Smoothing: Fine-tuned to 17 to capture wider item distribution cycles
    score += (post_residual % 17) as f64 * 1.8;

    // 3. Lookahead Optimization: Non-linear fit-bonus for immediate future items
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let fit_bonus = 110.0 + (next_item_size as f64 * 1.25);
            score -= if post_residual == next_item_size { fit_bonus * 5.8 } else { fit_bonus * 2.4 };
        } else if post_residual > 0 {
            score += 130.0 * (1.0 - (post_residual as f64 / next_item_size as f64).powf(1.5));
        }
    }

    // 4. Fitting Scarcity: Increased penalty for opening new bins when existing ones can suffice
    if fitting_bins_count > 0 && fitting_bins_count <= 22 {
        score -= (23.0 - fitting_bins_count as f64).powf(3.1) * 65.0;
    }

    // 5. New Bin Adaptive Cost: Dynamic penalty based on global residual pressure
    if is_new_bin {
        let avg_fill = (bin_capacity as f64 - mean_residual) / bin_capacity as f64;
        score += 185.0 - (avg_fill * 130.0) + (progress * 310.0);
        if mean_residual < 32.0 { score += 75.0; }
        if item_size < 45 { score += 115.0; }
    } else {
        score -= progress * 160.0;
    }

    // 6. Fill Density Bias: Aggressive quadratic reward for high-utilization
    if fill_ratio > 0.40 {
        score -= 160.0 * (fill_ratio.powi(2));
    }

    // 7. Variance Damping: Stricter adherence to mean residual
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 5.8;

    // 8. Global Coupling: Non-linear penalty for fragmentation
    if open_bins_count > 3 && progress < 0.95 {
        score += (open_bins_count as f64 * 7.2) * (1.0 + progress.sqrt());
    }

    // 9. Residual Tail-End Check: Hard penalty for microscopic gaps (increased to 18)
    if post_residual > 0 && post_residual < 18 {
        score += 135.0;
    }

    // 10. Density-Residual Interaction: If bin is nearly full, prioritize perfect fits
    if fill_ratio > 0.94 && post_residual < 22 {
        score -= 115.0;
    }

    // 11. Anti-fragmentation: Mid-to-large item specific consolidation
    if item_size > 35 && item_size < 85 && post_residual > 0 && post_residual < 35 {
        score -= 75.0 * (1.0 - (post_residual as f64 / 35.0));
    }

    // 12. Large Item Anchor: Strongly incentivize placing large items in existing bins
    if item_size > 60 && !is_new_bin {
        score -= 95.0;
    }

    // 13. Late-stage compaction: Aggressive final sweep
    if progress > 0.85 && !is_new_bin {
        score -= (post_residual as f64) * 0.85;
    }

    score
}

