    let post_res_f = post_residual as f64;

    // Base score: prioritize tighter fits (lower post_residual).
    // We add a penalty for creating "dead space" (post_residual < 10) 
    // as these are often hard to fill later, but keep it smooth.
    let mut score = post_res_f + (100.0 / (post_res_f + 1.0));

    // Lookahead logic: If the next item is large, avoid leaving small residuals.
    // If next_item_size > post_residual, this bin is effectively "closing" for that item.
    if next_item_size > 0 && next_item_size > post_residual {
        score += 20.0 * (1.0 - progress);
    }

    // Dynamic thresholding: As the stream progresses, become more aggressive 
    // about filling bins (Best-Fit behavior) and less tolerant of new bins.
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin: decreases as the stream nears the end,
        // but remains high enough to favor existing bins.
        score += 45.0 * (1.0 - progress * 0.5);
    } else {
        // Reward bins that bring the mean residual closer to the next_item_size,
        // creating a "self-organizing" packing effect.
        let deviation = (post_res_f - (next_item_size as f64)).abs();
        score -= (10.0 - (deviation * 0.1)).max(0.0) * progress;
    }

    // Penalize fragmented states where only one bin can fit the current item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0; 
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // 1. Refined Dead Zone: Heavily penalize mid-range residuals that prevent future placement
    if post_residual > 0 && post_residual < 52 {
        score += 135.0 + (52.0 - post_residual as f64) * 10.2;
    }

    // 2. Harmonic Residual Smoothing: Favor residuals that align with common item distributions
    score += (post_residual % 14) as f64 * 1.6;

    // 3. Lookahead Optimization: Tighten fit-bonus logic
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let fit_bonus = 110.0 + (next_item_size as f64 * 1.25);
            score -= if post_residual == next_item_size { fit_bonus * 5.5 } else { fit_bonus * 2.8 };
        } else if post_residual > 0 {
            score += 140.0 * (1.0 - (post_residual as f64 / next_item_size as f64));
        }
    }

    // 4. Fitting Scarcity: Exponentially punish opening new bins when capacity is available
    if fitting_bins_count > 0 && fitting_bins_count <= 20 {
        score -= (21.0 - fitting_bins_count as f64).powf(2.9) * 58.0;
    }

    // 5. New Bin Adaptive Cost: Increased cost for new bins, scaling with progress
    if is_new_bin {
        let avg_fill = (bin_capacity as f64 - mean_residual) / bin_capacity as f64;
        score += 185.0 - (avg_fill * 125.0) + (progress * 310.0);
        if mean_residual < 32.0 { score += 65.0; }
        if item_size < 45 { score += 110.0; }
    } else {
        score -= progress * 155.0;
    }

    // 6. Fill Density Bias: Quadratic reward for high-utilization
    if fill_ratio > 0.40 {
        score -= 150.0 * (fill_ratio.powi(2));
    }

    // 7. Variance Damping: Penalize bins that deviate from the global mean residual
    let dev = (post_residual as f64 - mean_residual).abs();
    if dev > 3.0 {
        score += dev * 5.5;
    }

    // 8. Global Coupling: Penalize open bin count to force consolidation
    if open_bins_count > 2 {
        score += (open_bins_count as f64 * 7.2) * (1.0 + progress * 0.5);
    }

    // 9. Residual Tail-End Check: Hard penalty for microscopic gaps
    if post_residual > 0 && post_residual < 16 {
        score += 115.0;
    }

    // 10. Density-Residual Interaction: If bin is nearly full, prioritize perfect fits
    if fill_ratio > 0.90 && post_residual < 22 {
        score -= 105.0;
    }

    // 11. Anti-fragmentation: Specifically target mid-to-large items
    if item_size > 35 && item_size < 85 && post_residual > 0 && post_residual < 35 {
        score -= 75.0 * (1.0 - (post_residual as f64 / 35.0));
    }

    // 12. Strategic New Bin Avoidance: Bonus for fitting large items in existing bins
    if item_size > 50 && !is_new_bin {
        score -= 90.0;
    }

    // 13. Late-stage compaction correction
    if progress > 0.85 && !is_new_bin {
        score -= (post_residual as f64) * 0.8;
    }

    score
}

