    // to keep the bin distribution uniform, reducing the chance of creating isolated empty bins.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.5;

    // If this is a new bin (bin_residual == bin_capacity), we add a base cost to prevent 
    // opening new bins unless the existing bins are extremely poor fits.
    if bin_residual == bin_capacity {
        // Base cost for opening a new bin is scaled by how many bins are already open 
        // and the current progress of the stream.
        let progress = step_index as f64 / total_items as f64;
        score += 35.0 + (open_bins_count as f64 * 2.0) - (progress * 10.0);
    } else {
        // For existing bins, favor bins that are nearly full (Best-Fit logic).
        // This is implicitly handled by the base score being post_residual, 
