        score -= (bin_capacity - bin_residual) as f64 * 0.1;
    }

    // Penalty for "wasting" the last chance: if fitting_bins_count == 1,
    // we are at a critical decision point.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    score
}

