        score -= (post_residual as f64) * 0.85;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals (fragmentation)
    // We favor bins that become very tight (post_residual near 0)
    score += (post_residual as f64).powf(1.5);

    // 2. Harmonic Class Logic: Reward residuals that are perfect multiples of common item sizes
    // This creates "bins of specific types" (e.g., bins that prefer 25s, 33s, or 50s)
    let harmonic_resonance = (post_residual % 25) as f64;
    score += harmonic_resonance * 2.0;

    // 3. Lookahead Synergy: If the next item fits into the post_residual, drastically reduce score
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 60.0;
        // Further reward if the post-post residual is near zero (perfect pair packing)
        if (post_residual - next_item_size) < 10 {
            score -= 40.0;
        }
    }

    // 4. New Bin Thresholding: Prevent opening new bins unless the current options are terrible
    if bin_residual == bin_capacity {
        // Only open a new bin if the average residual is already high (meaning existing bins are poorly packed)
        // or if we are forced to (fitting_bins_count == 0)
        if fitting_bins_count > 0 {
            score += 150.0 + (mean_residual * 2.0);
        } else {
            score -= 50.0;
        }
    }

    // 5. Progression Scaling: As the stream nears completion, become more aggressive with packing
    let progress = step_index as f64 / total_items as f64;
    score += progress * 20.0;

    // 6. Crowding Penalty: Avoid opening too many bins if the current bin is "good enough"
    score += (open_bins_count as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // 1. Adaptive Dead Zone: Penalize residuals that create unusable space
    if post_residual > 0 && post_residual < 52 {
        score += 145.0 + (52.0 - post_residual as f64) * 11.5;
    }

    // 2. Harmonic Residual Smoothing: Offset to prevent bin-syncing issues
    score += (post_residual % 19) as f64 * 1.9;

    // 3. Lookahead Optimization: Tightened anticipation for next item fit
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let fit_bonus = 120.0 + (next_item_size as f64 * 1.4);
            score -= if post_residual == next_item_size { fit_bonus * 6.0 } else { fit_bonus * 2.9 };
        } else if post_residual > 0 {
            score += 150.0 * (1.0 - (post_residual as f64 / next_item_size as f64));
        }
    }

    // 4. Fitting Scarcity: Exponentially punish opening new bins when capacity is available
    if fitting_bins_count > 0 && fitting_bins_count <= 24 {
        score -= (25.0 - fitting_bins_count as f64).powf(3.2) * 70.0;
    }

    // 5. New Bin Adaptive Cost: Discourage early fragmentation, adjusted for late-game density
    if is_new_bin {
        let avg_fill = (bin_capacity as f64 - mean_residual) / bin_capacity as f64;
        score += 225.0 - (avg_fill * 150.0) + (progress * 380.0);
        if mean_residual < 30.0 { score += 90.0; }
        if item_size < 48 { score += 130.0; }
    } else {
        score -= progress * 185.0;
    }

    // 6. Fill Density Bias: Non-linear reward for high-utilization
    if fill_ratio > 0.40 {
        score -= 200.0 * (fill_ratio.powi(2));
    }

    // 7. Variance Damping: Penalize deviation from mean to ensure uniform bins
    let dev = (post_residual as f64 - mean_residual).abs();
    if dev > 6.0 {
        score += dev * 7.0;
    }

    // 8. Global Coupling: Force consolidation by penalizing excess open bins
    if open_bins_count > 2 && progress < 0.98 {
        score += (open_bins_count as f64 * 12.0) * (1.0 + progress);
    }

    // 9. Residual Tail-End Check: Penalize gaps too small for common items
    if post_residual > 0 && post_residual < 20 {
        score += 140.0;
    }

    // 10. Density-Residual Interaction: Prioritize tight fits in full bins
    if fill_ratio > 0.88 && post_residual < 28 {
        score -= 130.0;
    }

    // 11. Anti-fragmentation: Targeted reduction of middle-sized waste
    if item_size > 25 && item_size < 95 && post_residual > 0 && post_residual < 45 {
        score -= 95.0 * (1.0 - (post_residual as f64 / 45.0));
    }

    // 12. Strategic New Bin Avoidance: Large item preference for existing bins
    if item_size > 50 && !is_new_bin {
        score -= 120.0;
    }

    // 13. Late-stage compaction correction
    if progress > 0.70 && !is_new_bin {
        score -= (post_residual as f64) * 1.1;
    }

    score
}
